"""
esuite_sync.py - Synchronisation von Daten mit der eSuite API.
"""

import logging
import time

import mariadb
import pandas as pd
import requests

from ..config_service import get_esuite_api_config
from ..db.client import connect_to_db
from ..utils.http_utils import retry_request
from ..utils.progress_logging import iter_with_progress

logger = logging.getLogger(__name__)


def _update_missing_references(
    select_query: str,
    update_query: str,
    id_column: str,
    reference_type: str,
    label: str,
) -> bool:
    """Aktualisiert fehlende eSuite-Referenzen fuer eine DB-Abfrage."""
    connection = connect_to_db()
    cursor = None
    try:
        cursor = connection.cursor()
        cursor.execute(select_query)
        df = pd.DataFrame(cursor.fetchall(), columns=[id_column])
        api_config = get_esuite_api_config("PROD")
        url_base = api_config.resthost + "resources"

        for index, row in iter_with_progress(logger, df.iterrows(), len(df), f"{label}References aktualisieren"):
            time.sleep(0.01)
            item_id = str(row[id_column])
            params = {"referenceType": reference_type, "id": item_id}
            try:
                response = retry_request("POST", url_base, json=params, headers=api_config.headers, verify=False)
                if response is None:
                    logger.error("Keine Antwort fuer %s %s, ueberspringe.", label, item_id)
                    continue

                response_text = response.text
                df.at[index, "Response"] = response_text
                cursor.execute(update_query, (response_text, item_id))
                connection.commit()
            except requests.RequestException as exc:
                logger.error("Request failed for %s %s: %s", label, item_id, exc, exc_info=True)
                raise

        return True
    except mariadb.Error as exc:
        logger.error("Fehler bei der Ausfuehrung der Abfrage: %s", exc, exc_info=True)
        raise
    finally:
        if cursor:
            cursor.close()
        connection.close()


def update_subscription_references() -> bool:
    """Aktualisiert die SubscriptionReferences in der tabelle tb_subscriptionsreport_ff."""
    logger.info("Starte Aktualisierung der SubscriptionReferences")
    result = _update_missing_references(
        select_query=(
            "SELECT subscriptionid FROM tb_subscriptionsreport_ff "
            "WHERE SubscriptionReference = '' or SubscriptionReference is null"
        ),
        update_query="UPDATE tb_subscriptionsreport_ff SET SubscriptionReference = ? WHERE subscriptionid = ?",
        id_column="subscriptionid",
        reference_type="S",
        label="Subscription",
    )
    logger.info("SubscriptionReference Update erfolgreich abgeschlossen")
    return result


def update_account_reference() -> bool:
    """Aktualisiert die AccountReferences in der tabelle tb_accountreport_faktur."""
    logger.info("Starte Aktualisierung der AccountReferences")
    result = _update_missing_references(
        select_query=(
            "SELECT accountid FROM tb_accountreport_faktur WHERE AccountReference = '' or AccountReference is null"
        ),
        update_query="UPDATE tb_accountreport_faktur SET AccountReference = ? WHERE accountid = ?",
        id_column="accountid",
        reference_type="A",
        label="Account",
    )
    logger.info("AccountReference Update erfolgreich abgeschlossen")
    return result
